<style>
.manuscript-success-modal{position:fixed;inset:0;z-index:2050;display:none;place-items:center;padding:1rem;background:rgba(8,25,45,.42);backdrop-filter:blur(4px)}.manuscript-success-modal.is-open{display:grid}.manuscript-success-dialog{position:relative;overflow:hidden;width:min(100%,24rem);padding:2.2rem 1.75rem;text-align:center;border:1px solid #d4f2df;border-radius:20px;background:#fff;box-shadow:0 28px 70px rgba(0,72,42,.28)}.manuscript-success-dialog h2{position:relative;margin:0 0 .45rem;color:#12643a;font-size:1.25rem;font-weight:800}.manuscript-success-dialog p{position:relative;margin:0;color:#587165;font-size:.84rem;line-height:1.6}.manuscript-success-check{position:relative;display:grid;place-items:center;width:62px;height:62px;margin:0 auto 1rem;border-radius:50%;background:#dcfce7;color:#15803d;font-size:2rem;box-shadow:0 0 0 9px #f0fdf4}.manuscript-flare{position:absolute;inset:0;pointer-events:none}.manuscript-flare i{position:absolute;top:50%;left:50%;width:8px;height:8px;border-radius:2px;background:#f59e0b;transform:translate(-50%,-50%);animation:manuscript-flare .9s ease-out forwards}.manuscript-flare i:nth-child(2n){background:#22c55e}.manuscript-flare i:nth-child(3n){background:#38bdf8}.manuscript-flare i:nth-child(1){--x:-100px;--y:-70px}.manuscript-flare i:nth-child(2){--x:102px;--y:-52px}.manuscript-flare i:nth-child(3){--x:-112px;--y:43px}.manuscript-flare i:nth-child(4){--x:108px;--y:64px}.manuscript-flare i:nth-child(5){--x:-37px;--y:-102px}.manuscript-flare i:nth-child(6){--x:44px;--y:104px}@keyframes manuscript-flare{from{opacity:1;transform:translate(-50%,-50%) scale(.3) rotate(0)}to{opacity:0;transform:translate(calc(-50% + var(--x)),calc(-50% + var(--y))) scale(1.4) rotate(160deg)}}
</style>
