<script>(function(){var modal=document.getElementById('manuscript-success-modal'),button=document.getElementById('manuscript-success-close');if(!modal)return;setTimeout(function(){modal.classList.add('is-open');},90);button.addEventListener('click',function(){modal.classList.remove('is-open');});modal.addEventListener('click',function(event){if(event.target===modal)modal.classList.remove('is-open');});})();</script>
